import java.util.*;

class Solution {
    public long[] gcdLcm(int a, int b) {
        long x = a, y = b;
        while (y != 0) {                     // Euclid: gcd(x, y) = gcd(y, x % y)
            long r = x % y;
            x = y;
            y = r;
        }
        long g = x;
        long lcm = (long) a / g * b;         // divide first, multiply in long
        return new long[] { g, lcm };
    }
}

